<style>
.ca50-product-page{background:linear-gradient(180deg,#eef9ff,#fff);padding:0 0 64px;color:#203548}
.ca50-detail-container{width:min(1240px,calc(100% - 48px));margin:auto}
.ca50-product-breadcrumb{display:flex;flex-wrap:wrap;gap:10px;padding:24px 0;font-size:12px;line-height:1.8;color:#678093}
.ca50-product-breadcrumb [aria-current]{color:#203548}
.ca50-product-overview{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:42px;padding:32px;background:white;border:1px solid #dcecf5;border-radius:24px;box-shadow:0 12px 40px #0876b508}
.ca50-product-gallery,.ca50-product-info{min-width:0}
.ca50-product-main-image{width:100%;height:430px;object-fit:contain;background:#f1f8fc;border-radius:18px}
.ca50-product-thumbs{display:flex;gap:10px;overflow-x:auto;padding:16px 2px 3px}
.ca50-product-thumbs button{flex:0 0 78px;background:white;border:1px solid #dcecf5;border-radius:12px;padding:4px;cursor:pointer}
.ca50-product-thumbs button[aria-pressed=true]{border-color:var(--ca-blue);box-shadow:0 0 0 1px var(--ca-blue)}
.ca50-product-thumbs img{width:68px;height:60px;object-fit:contain;border-radius:8px}
.ca50-product-category{display:inline-block;padding:7px 12px;background:var(--ca-pale);border-radius:20px;color:var(--ca-deep);font-size:12px;font-weight:600}
.ca50-product-info h1{font-size:30px;line-height:1.4;margin:16px 0;overflow-wrap:anywhere}
.ca50-product-meta{display:flex;flex-wrap:wrap;gap:16px;font-size:12px;color:#687f8f;padding-bottom:22px;border-bottom:1px solid #e6eff5}
.ca50-product-price{font-size:32px;font-weight:700;color:var(--ca-deep);margin-top:22px}
.ca50-product-old-price{display:inline-block;margin-top:6px;color:#8698a6;font-size:15px}
.ca50-product-summary,.ca50-product-highlights{font-size:14px;line-height:1.9;color:#536d80}
.ca50-product-highlights{padding-left:20px}
.ca50-product-buy{border-top:1px solid #e6eff5;margin-top:22px;padding-top:22px}
.ca50-product-buy label{display:block;font-size:13px;font-weight:600;margin-bottom:12px}
.ca50-product-buy>div{display:flex;gap:12px}
.ca50-product-buy input{width:84px;min-width:0;border:1px solid #cfe2ed;border-radius:12px;padding:13px;font:inherit}
.ca50-product-buy button{flex:1;display:flex;align-items:center;justify-content:center;gap:10px;min-height:50px;padding:12px 18px;border:0;border-radius:12px;background:var(--ca-blue);color:#fff;font:600 14px 'Be Vietnam Pro',sans-serif;cursor:pointer}
.ca50-product-buy button:hover{background:var(--ca-deep)}
.ca50-product-buy button:disabled{opacity:.5;cursor:not-allowed}
.ca50-product-description{margin-top:28px;padding:30px 32px;background:#fff;border:1px solid #dcecf5;border-radius:22px}
.ca50-product-description h2,.ca50-product-recommendations h2{font-size:24px;line-height:1.4;margin:0 0 22px}
.ca50-prose{font-size:15px;line-height:1.9;overflow-wrap:anywhere;overflow-x:auto}
.ca50-product-description .ca50-prose img{max-width:100%;height:auto;border-radius:12px}
.ca50-product-description table{border-collapse:collapse;width:100%}.ca50-product-description td,.ca50-product-description th{padding:12px;border:1px solid #dcecf5;text-align:left}
.ca50-product-recommendations{margin-top:44px}
.ca50-product-recommendations header{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:24px}
.ca50-product-recommendations h2{margin:0}.ca50-product-recommendations header>a{font-size:13px;color:var(--ca-deep);white-space:nowrap}
.ca50-detail-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}
.ca50-product-page .ca50-product-card{text-align:left;background:#fff;border:1px solid #dcecf5;border-radius:18px}
.ca50-product-page .ca50-product-image{display:block;height:210px;background:#f1f8fc}
.ca50-product-page .ca50-product-image img{object-fit:contain;transition:transform .2s}
.ca50-product-page .ca50-product-image:hover img{transform:scale(1.03)}
.ca50-product-page .ca50-product-card h3{font-size:14px;line-height:1.6;min-height:0;font-weight:600}
.ca50-product-page .ca50-product-card strong{font-size:17px}
.ca50-product-page :focus-visible{outline:3px solid var(--ca-orange);outline-offset:3px}
@media(max-width:900px){.ca50-product-overview{gap:26px;padding:24px}.ca50-product-main-image{height:340px}.ca50-product-info h1{font-size:25px}.ca50-detail-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:640px){.ca50-detail-container{width:calc(100% - 32px)}.ca50-product-overview{grid-template-columns:1fr;padding:18px;border-radius:18px}.ca50-product-main-image{height:290px}.ca50-product-info h1{font-size:24px}.ca50-product-price{font-size:28px}.ca50-product-buy>div{flex-wrap:wrap}.ca50-product-buy button{flex-basis:100%}.ca50-product-description{padding:22px}.ca50-product-description h2,.ca50-product-recommendations h2{font-size:20px}.ca50-detail-grid{gap:12px}.ca50-product-page .ca50-product-image{height:160px}.ca50-product-page .ca50-product-card>div{padding:12px}.ca50-product-page .ca50-product-card strong{font-size:14px}.ca50-product-recommendations header{align-items:flex-start}.ca50-product-page{padding-bottom:32px}}
</style>
